"use client"

import type { KeyboardEvent as ReactKeyboardEvent, ReactNode, RefObject } from "react"
import { cx } from "../lib/utils/cx"
import { XIcon } from "../combobox/internal"

/* Removable chips shared by TagInput and MultiSelect. Unexported from the package. */

/* Paper Layers: a small sage paper chip; the one about to go (or focused) turns ink. */
const chipClass = cx(
  "kg-tag-input__chip inline-flex items-center gap-0.5 max-w-full min-h-6 h-[calc(var(--_h)-var(--kg-space)*3)] ps-2.5 pe-0.75",
  "text-[0.92em] leading-none text-kg-fg bg-kg-paper-sage border-2 border-kg-ink rounded-full",
  "animate-[kg-pop-in_var(--kg-duration-base)_var(--kg-ease-out)] [--kg-enter-y:0px]",
  "transition-colors duration-(--kg-duration-fast) ease-kg-out",
  "data-pending:bg-kg-accent data-pending:text-kg-accent-fg",
  "has-focus-visible:bg-kg-accent has-focus-visible:text-kg-accent-fg",
)

const chipLabelClass =
  "kg-tag-input__chip-label inline-flex items-center gap-[0.15em] overflow-hidden text-ellipsis whitespace-nowrap"

const chipRemoveClass = cx(
  "kg-tag-input__chip-remove inline-grid place-items-center shrink-0 size-4.5 p-0 border-0 rounded-full",
  "bg-transparent text-inherit cursor-pointer [&_svg]:size-3",
  "transition-[background-color,color] duration-(--kg-duration-fast) ease-kg-out",
  "interactive:hover:bg-kg-surface interactive:hover:text-kg-fg disabled:cursor-not-allowed",
  "focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-kg-ring",
)

export interface ChipProps {
  label: ReactNode
  removeLabel: string
  index: number
  pending?: boolean
  disabled?: boolean
  onRemove: () => void
  onKeyDown: (event: ReactKeyboardEvent<HTMLButtonElement>, index: number) => void
}

export const Chip = ({
  label,
  removeLabel,
  index,
  pending,
  disabled,
  onRemove,
  onKeyDown,
}: ChipProps) => (
  <span className={chipClass} data-pending={pending || undefined}>
    <span className={chipLabelClass}>{label}</span>
    <button
      type="button"
      tabIndex={-1}
      data-chip={index}
      className={chipRemoveClass}
      aria-label={removeLabel}
      disabled={disabled}
      onMouseDown={(event) => event.preventDefault()}
      onClick={onRemove}
      onKeyDown={(event) => onKeyDown(event, index)}
    >
      <XIcon />
    </button>
  </span>
)

/**
 * Arrow keys walk the chips from the input, Backspace and Delete remove the focused one, and
 * focus always lands somewhere sensible afterwards.
 */
export const useChipKeys = (
  groupRef: RefObject<HTMLElement | null>,
  inputRef: RefObject<HTMLInputElement | null>,
  count: number,
  remove: (index: number) => void,
) => {
  const focusChip = (index: number) => {
    const chip = groupRef.current?.querySelector<HTMLButtonElement>(`[data-chip="${index}"]`)
    chip?.focus()
  }
  const onChipKeyDown = (event: ReactKeyboardEvent<HTMLButtonElement>, index: number) => {
    switch (event.key) {
      case "ArrowLeft":
        event.preventDefault()
        focusChip(Math.max(0, index - 1))
        return
      case "ArrowRight":
        event.preventDefault()
        if (index >= count - 1) inputRef.current?.focus()
        else focusChip(index + 1)
        return
      case "Backspace":
      case "Delete":
        event.preventDefault()
        remove(index)
        if (count <= 1) inputRef.current?.focus()
        else requestAnimationFrame(() => focusChip(Math.max(0, Math.min(index - 1, count - 2))))
        return
      case "Escape":
        inputRef.current?.focus()
    }
  }
  return { focusChip, onChipKeyDown }
}

"use client"

import {
  type ClipboardEvent,
  forwardRef,
  type InputHTMLAttributes,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../lib/hooks/use-controllable-state"
import { useComposedRefs } from "../lib/utils/compose-refs"
import { cx } from "../lib/utils/cx"
import { resolveFieldControl, useField } from "../field/field"
import {
  type InputGroupSize,
  inputGroupControl,
  inputGroupVariants,
} from "../input-group/input-group"
import { Chip, useChipKeys } from "./chips"

export interface TagInputProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "defaultValue" | "onChange" | "size" | "type" | "name" | "prefix"
> {
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (tags: string[]) => void
  /** Keys besides Enter that turn the text into a tag. */
  delimiters?: string[]
  max?: number
  allowDuplicates?: boolean
  /** Return false to refuse a tag. */
  validate?: (tag: string, tags: readonly string[]) => boolean
  /** Shown before every tag, e.g. a hash. */
  prefix?: ReactNode
  removeLabel?: (tag: string) => string
  size?: InputGroupSize
  invalid?: boolean
  /** Submits the tags comma-separated through a hidden input. */
  name?: string
}

/**
 * Free-form tags. Enter or a delimiter commits, paste splits on commas and new lines,
 * Backspace on an empty field marks the last tag and a second press removes it.
 */
export const TagInput = forwardRef<HTMLInputElement, TagInputProps>(
  (
    {
      value: valueProp,
      defaultValue = [],
      onValueChange,
      delimiters = [","],
      max,
      allowDuplicates = false,
      validate,
      prefix,
      removeLabel = (tag) => `Remove ${tag}`,
      size = "md",
      invalid,
      disabled,
      required,
      name,
      placeholder,
      id,
      className,
      style,
      onKeyDown,
      onBlur,
      onPaste,
      "aria-describedby": describedBy,
      "aria-errormessage": errorMessage,
      ...props
    },
    forwardedRef,
  ) => {
    const control = resolveFieldControl(useField(), {
      id,
      disabled,
      required,
      invalid,
      "aria-describedby": describedBy,
      "aria-errormessage": errorMessage,
    })
    const [tags, setTags] = useControllableState({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    })
    const [text, setText] = useState("")
    const [pending, setPending] = useState(false)
    const groupRef = useRef<HTMLDivElement>(null)
    const inputRef = useRef<HTMLInputElement>(null)
    const ref = useComposedRefs(inputRef, forwardedRef)
    const full = max !== undefined && tags.length >= max

    const remove = (index: number) => setTags(tags.filter((_, at) => at !== index))
    const { focusChip, onChipKeyDown } = useChipKeys(groupRef, inputRef, tags.length, remove)

    const add = (raw: readonly string[]) => {
      const next = [...tags]
      for (const piece of raw) {
        const tag = piece.trim()
        if (!tag) continue
        if (max !== undefined && next.length >= max) break
        if (!allowDuplicates && next.some((t) => t.toLowerCase() === tag.toLowerCase())) continue
        if (validate && !validate(tag, next)) continue
        next.push(tag)
      }
      if (next.length !== tags.length) setTags(next)
      return next.length !== tags.length
    }

    const handleKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
      onKeyDown?.(event)
      if (event.defaultPrevented) return
      const { key } = event
      if (key === "Enter" || delimiters.includes(key)) {
        if (!text.trim()) {
          if (key !== "Enter") event.preventDefault()
          return
        }
        event.preventDefault()
        // A tag that fails validation stays in the field so it can be corrected.
        if (validate && !validate(text.trim(), tags)) return
        add([text])
        setText("")
        return
      }
      const caretAtStart =
        event.currentTarget.selectionStart === 0 && event.currentTarget.selectionEnd === 0
      if (key === "Backspace" && text === "" && tags.length > 0) {
        event.preventDefault()
        if (pending) {
          remove(tags.length - 1)
          setPending(false)
        } else setPending(true)
        return
      }
      if (key === "ArrowLeft" && caretAtStart && tags.length > 0) {
        event.preventDefault()
        setPending(false)
        focusChip(tags.length - 1)
        return
      }
      setPending(false)
    }

    const handlePaste = (event: ClipboardEvent<HTMLInputElement>) => {
      onPaste?.(event)
      const data = event.clipboardData.getData("text")
      if (!/[,\n]/.test(data)) return
      event.preventDefault()
      add(data.split(/[,\n]/))
    }

    return (
      <>
        <div
          ref={groupRef}
          className={inputGroupVariants({
            size,
            multiline: true,
            // The data variant outranks the group's own gap.
            className: cx("kg-tag-input data-multiline:gap-1", className),
          })}
          style={style}
          data-size={size}
          data-multiline=""
          data-invalid={control.invalid || undefined}
          data-disabled={control.disabled || undefined}
          onPointerDown={(event) => {
            if (event.target === groupRef.current) {
              event.preventDefault()
              inputRef.current?.focus()
            }
          }}
        >
          {tags.map((tag, index) => (
            <Chip
              // Tags are unique unless duplicates are allowed, so the index breaks ties.
              key={`${tag}-${index}`}
              index={index}
              label={
                <>
                  {prefix != null && (
                    <span className="kg-tag-input__prefix opacity-65" aria-hidden="true">
                      {prefix}
                    </span>
                  )}
                  {tag}
                </>
              }
              removeLabel={removeLabel(tag)}
              pending={pending && index === tags.length - 1}
              disabled={control.disabled}
              onRemove={() => {
                remove(index)
                inputRef.current?.focus()
              }}
              onKeyDown={onChipKeyDown}
            />
          ))}
          <input
            ref={ref}
            id={control.id}
            type="text"
            className={inputGroupControl}
            autoComplete="off"
            enterKeyHint="enter"
            disabled={control.disabled}
            readOnly={full}
            placeholder={tags.length === 0 ? placeholder : undefined}
            aria-describedby={control.describedBy}
            aria-invalid={control.invalid || undefined}
            aria-errormessage={control.errorMessage}
            aria-required={control.required || undefined}
            value={text}
            onChange={(event) => {
              setText(event.target.value)
              setPending(false)
            }}
            onKeyDown={handleKeyDown}
            onPaste={handlePaste}
            onBlur={(event) => {
              onBlur?.(event)
              setPending(false)
              if (text.trim() && add([text])) setText("")
            }}
            {...props}
          />
        </div>
        {name !== undefined && <input type="hidden" name={name} value={tags.join(",")} />}
      </>
    )
  },
)

TagInput.displayName = "TagInput"
